"Quote of the day": "Zitat des Tages",
"Pray a Novena": "Eine Novene beten",
"Choose any saint as your patron and pray a nine-day novena. Sanctify keeps track of each day for you.": "Wähle einen beliebigen Heiligen als Patron und bete eine neuntägige Novene. Sanctify zählt jeden Tag für dich mit.",
"Feast Days": "Heiligenfeste",
