"Your language, how Sanctify looks, the edition you use, and the data kept on this device.": "Deine Sprache, das Aussehen von Sanctify, deine Ausgabe und die Daten auf diesem Gerät.",
"Sanctify is translated by hand into Spanish, Polish, French, Portuguese, Italian, German, Russian, and Ukrainian: menus, pages, and the common prayers. Longer texts, such as the lives of the saints, are still in English.": "Sanctify ist von Hand ins Spanische, Polnische, Französische, Portugiesische, Italienische, Deutsche, Russische und Ukrainische übersetzt: Menüs, Seiten und die gängigen Gebete. Längere Texte wie die Lebensbeschreibungen der Heiligen sind noch auf Englisch.",
