"Five decades · about {n} minutes": "Fünf Gesätze · etwa {n} Minuten",
"How to pray the Rosary": "Wie man den Rosenkranz betet",
"On the crucifix, make the Sign of the Cross and pray the Apostles’ Creed.": "Mache am Kreuz das Kreuzzeichen und bete das Apostolische Glaubensbekenntnis.",
"On the first large bead, pray the Our Father.": "Bete an der ersten großen Perle das Vaterunser.",
"On the next three beads, pray a Hail Mary each for faith, hope, and charity, then the Glory Be.": "Bete an den nächsten drei Perlen je ein Gegrüßet seist du, Maria, um Glaube, Hoffnung und Liebe, dann das Ehre sei dem Vater.",
"Announce the first mystery, and pray the Our Father on the large bead.": "Nenne das erste Geheimnis und bete an der großen Perle das Vaterunser.",
"On the ten small beads, pray ten Hail Marys while meditating on the mystery.": "Bete an den zehn kleinen Perlen zehn Gegrüßet seist du, Maria, und betrachte dabei das Geheimnis.",
"End the decade with the Glory Be and the Fatima Prayer. Repeat for the other four mysteries.": "Schließe das Gesätz mit dem Ehre sei dem Vater und dem Fatima-Gebet. Wiederhole es für die anderen vier Geheimnisse.",
"At the centerpiece, finish with the Hail, Holy Queen and the closing prayer.": "Schließe am Mittelstück mit dem Salve Regina und dem Schlussgebet.",
