"A novena is nine days of prayer for a particular intention. Open any saint or prayer and choose": "Eine Novene sind neun Tage Gebet in einem bestimmten Anliegen. Öffne einen beliebigen Heiligen oder ein Gebet und wähle",
"Keep a list of the people and needs you are praying for. When a prayer is answered, mark it and give thanks.": "Führe eine Liste der Menschen und Nöte, für die du betest. Wenn ein Gebet erhört wird, markiere es und danke.",
"Tap ☆ Save on any prayer, saint, book, or article to keep it here.": "Tippe bei einem Gebet, Heiligen, Buch oder Artikel auf ☆ Speichern, um es hier aufzubewahren.",
