"The Chaplet of Divine Mercy": "Der Barmherzigkeitsrosenkranz",
"Jesus, I trust in You": "Jesus, ich vertraue auf dich",
"Jesus, I trust in You.": "Jesus, ich vertraue auf dich.",
"Eternal Father": "Ewiger Vater",
"For the Sake of His Sorrowful Passion": "Durch sein schmerzhaftes Leiden",
"Holy God": "Heiliger Gott",
"Eternal Father, I offer You the Body and Blood, Soul and Divinity of Your dearly beloved Son, Our Lord Jesus Christ, in atonement for our sins and those of the whole world.": "Ewiger Vater, ich opfere dir auf den Leib und das Blut, die Seele und die Gottheit deines über alles geliebten Sohnes, unseres Herrn Jesus Christus, zur Sühne für unsere Sünden und die der ganzen Welt.",
"For the sake of His sorrowful Passion, have mercy on us and on the whole world.": "Durch sein schmerzhaftes Leiden hab Erbarmen mit uns und mit der ganzen Welt.",
"Holy God, Holy Mighty One, Holy Immortal One, have mercy on us and on the whole world.": "Heiliger Gott, heiliger starker Gott, heiliger unsterblicher Gott, hab Erbarmen mit uns und mit der ganzen Welt.",
"You expired, Jesus, but the source of life gushed forth for souls, and an ocean of mercy opened up for the whole world. O Fount of Life, unfathomable Divine Mercy, envelop the whole world and empty Yourself out upon us.": "Du bist gestorben, Jesus, aber die Quelle des Lebens ist für die Seelen hervorgesprudelt, und ein Meer der Barmherzigkeit hat sich für die ganze Welt geöffnet. O Quelle des Lebens, unergründliche Barmherzigkeit Gottes, umfange die ganze Welt und ergieße dich über uns.",
"Eternal God, in whom mercy is endless and the treasury of compassion inexhaustible, look kindly upon us and increase Your mercy in us, that in difficult moments we might not despair nor become despondent, but with great confidence submit ourselves to Your holy will, which is Love and Mercy itself.": "Ewiger Gott, deine Barmherzigkeit ist grenzenlos und der Schatz deines Erbarmens unerschöpflich. Blicke gütig auf uns und vermehre in uns deine Barmherzigkeit, damit wir in schweren Augenblicken nicht verzweifeln und nicht mutlos werden, sondern uns mit großem Vertrauen deinem heiligen Willen unterwerfen, der die Liebe und die Barmherzigkeit selbst ist.",
"How to pray the Chaplet": "Wie man den Barmherzigkeitsrosenkranz betet",
"Begin with the Sign of the Cross and the opening prayer.": "Beginne mit dem Kreuzzeichen und dem Eröffnungsgebet.",
"Pray one Our Father, one Hail Mary, and the Apostles’ Creed.": "Bete ein Vaterunser, ein Gegrüßet seist du, Maria, und das Apostolische Glaubensbekenntnis.",
"On each large bead, pray “Eternal Father, I offer You…”": "Bete an jeder großen Perle „Ewiger Vater, ich opfere dir auf…“",
"On each of the ten small beads, pray “For the sake of His sorrowful Passion…”": "Bete an jeder der zehn kleinen Perlen „Durch sein schmerzhaftes Leiden…“",
"It is the Hour of Mercy now.": "Jetzt ist die Stunde der Barmherzigkeit.",
"You have prayed the Chaplet of Divine Mercy": "Du hast den Barmherzigkeitsrosenkranz gebetet",
"Pray the Chaplet again": "Den Barmherzigkeitsrosenkranz noch einmal beten",
"The Chaplet of the Sacred Heart": "Der Herz-Jesu-Rosenkranz",
"Chaplet of the Sacred Heart": "Herz-Jesu-Rosenkranz",
"Sweet Heart of Jesus, be my love": "Süßes Herz Jesu, sei meine Liebe",
"Sweet Heart of Jesus, be my love.": "Süßes Herz Jesu, sei meine Liebe.",
"Sweet Heart of Mary": "Süßes Herz Mariä",
"Sweet Heart of Mary, be my salvation.": "Süßes Herz Mariä, sei meine Rettung.",
"O Sweetest Heart of Jesus": "O süßestes Herz Jesu",
"O Sweetest Heart of Jesus, I implore that I may ever love Thee more and more.": "O süßestes Herz Jesu, ich bitte dich, lass mich dich immer mehr und mehr lieben.",
"May the Heart of Jesus in the Most Blessed Sacrament be praised, adored, and loved with grateful affection, at every moment, in all the tabernacles of the world, even to the end of time. Amen.": "Das Herz Jesu im Allerheiligsten Sakrament sei gelobt, angebetet und geliebt mit dankbarer Liebe, in jedem Augenblick, in allen Tabernakeln der Welt, bis zum Ende der Zeiten. Amen.",
"Soul of Christ": "Seele Christi",
"Soul of Christ, sanctify me.": "Seele Christi, heilige mich.",
"Body of Christ, save me.": "Leib Christi, rette mich.",
"Blood of Christ, inebriate me.": "Blut Christi, tränke mich.",
"Water from the side of Christ, wash me.": "Wasser der Seite Christi, wasche mich.",
"Passion of Christ, strengthen me.": "Leiden Christi, stärke mich.",
"O good Jesus, hear me.": "O guter Jesus, erhöre mich.",
"Within thy wounds hide me.": "Birg in deinen Wunden mich.",
"Suffer me not to be separated from thee.": "Von dir lass nimmer scheiden mich.",
"From the malicious enemy defend me.": "Vor dem bösen Feind beschütze mich.",
"In the hour of my death call me": "In meiner Todesstunde rufe mich",
"and bid me come unto thee,": "zu dir zu kommen heiße mich,",
"that with thy saints I may praise thee": "mit deinen Heiligen zu loben dich",
"forever and ever. Amen.": "in Ewigkeit. Amen.",
"The pendant": "Der Anhänger",
"Thirty-three beads · about {n} minutes": "Dreiunddreißig Perlen · etwa {n} Minuten",
"On the crucifix, make the Sign of the Cross and pray the Soul of Christ (Anima Christi).": "Mache am Kreuz das Kreuzzeichen und bete die Seele Christi (Anima Christi).",
"On each small bead, pray “Sweet Heart of Jesus, be my love.”": "Bete an jeder kleinen Perle „Süßes Herz Jesu, sei meine Liebe.“",
"After each group of small beads, pray “Sweet Heart of Mary, be my salvation.”": "Bete nach jeder Gruppe kleiner Perlen „Süßes Herz Mariä, sei meine Rettung.“",
"You have prayed the Chaplet of the Sacred Heart": "Du hast den Herz-Jesu-Rosenkranz gebetet",
"Via Crucis": "Via Crucis",
"Walk the Way of the Cross": "Den Kreuzweg gehen",
