"Our Father · Hail Mary · Glory Be": "Vaterunser · Gegrüßet seist du, Maria · Ehre sei dem Vater",
"We adore You, O Christ, and we bless You,": "Wir beten dich an, Herr Jesus Christus, und preisen dich,",
"because by Your holy cross You have redeemed the world.": "denn durch dein heiliges Kreuz hast du die Welt erlöst.",
"We adore You, O Christ, and we bless You, because by Your holy cross You have redeemed the world.": "Wir beten dich an, Herr Jesus Christus, und preisen dich, denn durch dein heiliges Kreuz hast du die Welt erlöst.",
"Jesus is Condemned to Death": "Jesus wird zum Tode verurteilt",
