"The Mass and Divine Office of the day in Latin and English (Divinum Officium) ↗": "Messe und Stundengebet des Tages auf Latein und Englisch (Divinum Officium) ↗",
"Pray the Rosary bead by bead with the fifteen traditional mysteries, Joyful, Sorrowful, and Glorious, and a meditation for each.": "Bete den Rosenkranz Perle für Perle mit den fünfzehn überlieferten Geheimnissen, den freudenreichen, schmerzhaften und glorreichen, mit einer Betrachtung zu jedem.",
"Monday & Thursday": "Montag & Donnerstag",
"Wednesday, Saturday & Sunday": "Mittwoch, Samstag & Sonntag",
"The Latin Mass Explained": "Die lateinische Messe erklärt",
"Every part of the Traditional Latin Mass of 1962, with the Latin you will hear, when to kneel, sit, and stand, and what each moment means. Follow along on your phone.": "Jeder Teil der überlieferten lateinischen Messe von 1962, mit dem Latein, das du hören wirst, wann man kniet, sitzt und steht und was jeder Moment bedeutet. Verfolge sie auf deinem Handy.",
