"Fridays are days of penance throughout the year.": "Freitage sind das ganze Jahr über Bußtage.",
"The Lord’s Day: Mass is an obligation for Catholics.": "Tag des Herrn: Die Messe ist für Katholiken Pflicht.",
"A day of fasting and abstinence.": "Fast- und Abstinenztag.",
"A Friday of Lent: a day of abstinence from meat.": "Freitag der Fastenzeit: Abstinenz von Fleisch.",
"Kept on the Sunday between the Octave Day of Christmas and the Epiphany, or else on January 2.": "Gefeiert am Sonntag zwischen dem Oktavtag von Weihnachten und Erscheinung des Herrn, sonst am 2. Januar.",
"The First Sunday after the Epiphany.": "Erster Sonntag nach Erscheinung des Herrn.",
"The name means “seventieth,” counting toward Easter. The Gloria and Alleluia fall silent, and violet is worn until Easter.": "Der Name bedeutet „der siebzigste“, gezählt auf Ostern hin. Gloria und Halleluja verstummen, und bis Ostern wird Violett getragen.",
"Lent begins. Ashes are blessed and imposed: “Memento, homo, quia pulvis es, et in pulverem reverteris.”": "Die Fastenzeit beginnt. Die Asche wird gesegnet und aufgelegt: „Memento, homo, quia pulvis es, et in pulverem reverteris.“",
"An Ember Day: by tradition a day of fasting and prayer for the season, and for those to be ordained.": "Quatembertag: nach der Überlieferung ein Tag des Fastens und Gebets für die Jahreszeit und für die Weihekandidaten.",
"Named from the first word of its Introit, “Rejoice.” Rose vestments may be worn.": "Benannt nach dem ersten Wort seines Introitus: „Freut euch.“ Rosafarbene Gewänder können getragen werden.",
"Passiontide begins, and the crosses and images in the church are veiled.": "Die Passionszeit beginnt, und Kreuze und Bilder in der Kirche werden verhüllt.",
"Commemorated on the Friday after Passion Sunday.": "Gedacht am Freitag nach dem Passionssonntag.",
"The Second Sunday of the Passion. Palms are blessed and carried in procession.": "Zweiter Passionssonntag. Die Palmzweige werden gesegnet und in einer Prozession getragen.",
"The Mass of the Lord’s Supper, the washing of feet, and the stripping of the altars.": "Die Messe vom Letzten Abendmahl, die Fußwaschung und die Entblößung der Altäre.",
"The solemn afternoon liturgy of the Passion, with the adoration of the Cross. No Mass is said.": "Die feierliche nachmittägliche Liturgie vom Leiden des Herrn mit der Kreuzverehrung. Es wird keine Messe gefeiert.",
"The Easter Vigil is kept at night.": "Die Osternacht wird in der Nacht gefeiert.",
"The feast of feasts.": "Das Fest der Feste.",
"Within the octave of Easter.": "In der Osteroktav.",
"The Octave Day of Easter (Dominica in Albis).": "Oktavtag von Ostern (Dominica in Albis).",
"The Lesser Litanies: the Litany of the Saints is chanted, traditionally in procession, to ask God’s blessing on the fields.": "Kleine Litaneien: Die Allerheiligenlitanei wird, traditionell in einer Prozession, gesungen, um Gottes Segen für die Felder zu erbitten.",
"Forty days after Easter. The Paschal candle is extinguished after the Gospel.": "Vierzig Tage nach Ostern. Nach dem Evangelium wird die Osterkerze gelöscht.",
"The descent of the Holy Spirit upon the apostles.": "Die Herabkunft des Heiligen Geistes auf die Apostel.",
"Within the octave of Pentecost.": "In der Pfingstoktav.",
"The First Sunday after Pentecost.": "Erster Sonntag nach Pfingsten.",
"The feast of the Most Holy Body of Christ, with its procession of the Blessed Sacrament.": "Das Fest des Heiligsten Leibes Christi mit seiner Sakramentsprozession.",
"The Friday after the octave of Corpus Christi.": "Der Freitag nach der Fronleichnamsoktav.",
"Its Gospel speaks of the end of the world and the coming of the Son of Man.": "Ihr Evangelium spricht vom Ende der Welt und vom Kommen des Menschensohnes.",
"Kept on the last Sunday of October. Instituted by Pope Pius XI in 1925.": "Gefeiert am letzten Sonntag im Oktober. Von Papst Pius XI. 1925 eingeführt.",
"Every priest may say three Masses for the dead.": "Jeder Priester darf drei Messen für die Verstorbenen feiern.",
"Every priest may say three Masses for the dead. Kept on November 3 this year, because November 2 is a Sunday.": "Jeder Priester darf drei Messen für die Verstorbenen feiern. In diesem Jahr am 3. November, weil der 2. November ein Sonntag ist.",
