"Change this in Settings": "In den Einstellungen ändern",
"What moderators can do": "Was Moderatoren tun können",
"Reports:": "Meldungen:",
"members can report a post or reply. Review them here, then remove it or dismiss the report.": "Mitglieder können Beiträge oder Antworten melden. Prüfe sie hier und entferne den Inhalt oder verwirf die Meldung.",
"Accounts:": "Konten:",
"see every account with its posts and replies, ban a member for a day, a week, a month, or for good, and remove everything they have posted.": "jedes Konto mit seinen Beiträgen und Antworten sehen, ein Mitglied für einen Tag, eine Woche, einen Monat oder dauerhaft sperren und alles entfernen, was es gepostet hat.",
"Members:": "Mitglieder:",
"mute a member so they can read and pray but not post, send them a private warning, and keep private notes on their account.": "ein Mitglied stummschalten, sodass es lesen und beten, aber nicht posten kann, ihm eine private Verwarnung schicken und private Notizen zu seinem Konto führen.",
"Threads:": "Themen:",
"open any Community post to remove it, pin it to the top, lock it so it takes no new replies, or move it to another category.": "jeden Community-Beitrag öffnen, um ihn zu entfernen, oben anzuheften, für neue Antworten zu sperren oder in eine andere Kategorie zu verschieben.",
"Settings:": "Einstellungen:",
"make the whole Community read-only for a while, and keep a list of blocked words that can’t be posted.": "die ganze Community eine Zeit lang schreibschützen und eine Liste gesperrter Wörter führen, die nicht gepostet werden können.",
"News:": "Neuigkeiten:",
