"AutoMod": "AutoMod",
"Turns back spam before it’s posted, in posts, replies, descriptions, and wiki pages: links to other sites from accounts less than a day old, more than four links, writing in all capitals, long runs of one character, and the same text posted twice within an hour. Moderators aren’t affected. Everything it does is in the log.": "Hält Spam auf, bevor er erscheint, in Beiträgen, Antworten, Beschreibungen und Wiki-Seiten: Links auf andere Seiten von Konten, die jünger als ein Tag sind, mehr als vier Links, Text in Großbuchstaben, lange Ketten desselben Zeichens und derselbe Text zweimal innerhalb einer Stunde. Moderatoren sind ausgenommen. Alles, was es tut, steht im Protokoll.",
"Hide a post or reply until a moderator looks at it once": "Einen Beitrag oder eine Antwort bis zur Prüfung durch einen Moderator ausblenden, sobald",
"different members report it.": "verschiedene Mitglieder ihn melden.",
"Blocked words": "Gesperrte Wörter",
"Posts and replies that use any of these words (as a whole word) are turned back with a request to rephrase. One word or phrase per line. Moderators aren’t affected.": "Beiträge und Antworten mit einem dieser Wörter (als ganzes Wort) werden mit der Bitte um Umformulierung zurückgewiesen. Ein Wort oder Ausdruck pro Zeile. Moderatoren sind ausgenommen.",
